-- The basic department questionnaire joins the platform library: about thirty questions every
-- department answers twice a year, each naming the ISO 9001, JCI and TEMOS points it speaks to.
-- Generated from src/features/quality/audits/seed/core.js (tests/auditProgramme.test.js checks they agree).

with s as (select '{"k":"core","s":"other","v":"Κοινό ερωτηματολόγιο","t":"Βασικό ερωτηματολόγιο τμήματος (ISO 9001 · JCI · TEMOS)","d":"Σύντομο κοινό ερωτηματολόγιο για κάθε τμήμα, δύο φορές τον χρόνο: περίπου 30 ερωτήσεις σε 8 ενότητες, με αναφορά στα σημεία των ISO 9001, JCI και TEMOS που καλύπτει η καθεμιά. Δεν αποτελεί το κείμενο του προτύπου.","sc":"Όλα τα τμήματα και οι μονάδες του νοσοκομείου.","dt":[],"ch":[{"r":"ΑΣΦ","t":"Ασφάλεια ασθενών και φαρμάκων","q":[["JCI IPSG.1 · ISO 9001 8.5","Ταυτοποιούνται οι ασθενείς με δύο στοιχεία (όνομα και ημερομηνία γέννησης) πριν από κάθε φάρμακο, εξέταση ή επέμβαση;","Παρατήρηση, φάκελοι","Δείγμα τριών φακέλων και δύο παρατηρήσεις.",2,true,[]],["JCI IPSG.2 · TEMOS T2","Επιβεβαιώνονται οι προφορικές και τηλεφωνικές εντολές και τα κρίσιμα αποτελέσματα με επανάληψη και καταγραφή (read-back);","Φάκελοι, συνέντευξη","",2,true,[]],["JCI IPSG.3 · MMU","Φυλάσσονται τα φάρμακα υψηλού κινδύνου (π.χ. πυκνά ηλεκτρολυτικά διαλύματα) σε σημασμένο και ασφαλές σημείο;","Επιθεώρηση φαρμακείου τμήματος","",2,true,[]],["JCI MMU · ISO 9001 8.5.1","Ελέγχονται κάθε μήνα οι ημερομηνίες λήξης φαρμάκων και υλικών και καταγράφεται ο έλεγχος;","Φύλλο ελέγχου","",1,false,[]],["JCI IPSG.6 · ISO 9001 8.5","Αξιολογείται ο κίνδυνος πτώσης στους ασθενείς κατά την εισαγωγή και λαμβάνονται μέτρα όπου χρειάζεται;","Φάκελοι","",1,false,[]]]},{"r":"ΛΟΙ","t":"Λοιμώξεις και υγιεινή","q":[["JCI IPSG.5 · PCI","Εφαρμόζεται η υγιεινή των χεριών στις πέντε στιγμές, και υπάρχει αντισηπτικό στο σημείο φροντίδας;","Παρατήρηση, καταγραφή συμμόρφωσης","",2,true,[]],["JCI PCI · ISO 9001 8.5","Εφαρμόζονται τα μέτρα απομόνωσης και προφύλαξης ανάλογα με τον λοιμογόνο παράγοντα του ασθενούς;","Παρατήρηση, πινακίδες","",1,false,[]],["JCI PCI · ISO 9001 7.1.4","Διαχειρίζονται σωστά τα αιχμηρά και τα μολυσματικά απορρίμματα (κατάλληλοι κάδοι, όχι υπερπλήρεις);","Επιθεώρηση χώρου","",1,false,[]],["JCI PCI.7 · ISO 9001 7.1.3","Καθαρίζονται και απολυμαίνονται οι επιφάνειες και ο εξοπλισμός με πρόγραμμα και καταγραφή;","Φύλλο καθαρισμού","",1,false,[]]]},{"r":"ΕΞΟ","t":"Εξοπλισμός και χώρος","q":[["JCI FMS.8 · ISO 9001 7.1.5","Έχουν ισχύουσα συντήρηση ή διακρίβωση οι κρίσιμες συσκευές του τμήματος και φέρουν σήμανση;","Μητρώο εξοπλισμού, ετικέτες","",2,true,[]],["JCI FMS · ISO 9001 7.1.4","Είναι ελεύθερες και σημασμένες οι έξοδοι διαφυγής, και είναι σε ισχύ ο εξοπλισμός πυροπροστασίας;","Επιθεώρηση χώρου","",1,false,[]],["JCI FMS.7 · ISO 9001 8.5.4","Υπάρχει και είναι έτοιμος ο εξοπλισμός επείγουσας ανάνηψης, με καταγεγραμμένο έλεγχο;","Φύλλο ελέγχου καροτσιού ανάνηψης","",2,true,[]],["ISO 9001 7.1.3 · TEMOS T5","Είναι καθαρός, ασφαλής και σε καλή κατάσταση ο χώρος νοσηλείας και αναμονής;","Επιθεώρηση χώρου","",1,false,[]]]},{"r":"ΤΕΚ","t":"Τεκμηρίωση και έγγραφα","q":[["ISO 9001 7.5 · JCI MOI","Είναι ενημερωμένα, εγκεκριμένα και προσβάσιμα στο προσωπικό τα πρωτόκολλα και οι οδηγίες του τμήματος;","Έλεγχος εγγράφων","",1,false,[]],["JCI MOI.10 · ISO 9001 7.5.3","Συμπληρώνονται πλήρως, με υπογραφή και ώρα, οι ιατρικοί και νοσηλευτικοί φάκελοι;","Δείγμα φακέλων","",1,false,[]],["JCI PFR · ISO 9001 8.2.1 · TEMOS T3","Υπάρχει ενυπόγραφη ενημερωμένη συγκατάθεση πριν από επεμβατικές πράξεις και θεραπείες;","Φάκελοι","",2,true,[]],["ISO 9001 7.5 · JCI MOI","Φυλάσσονται και προστατεύονται τα προσωπικά δεδομένα των ασθενών (φάκελοι, οθόνες, κλειδωμένοι χώροι);","Επιθεώρηση χώρου","",1,false,[]]]},{"r":"ΠΡΟ","t":"Προσωπικό και εκπαίδευση","q":[["JCI SQE · ISO 9001 7.2","Έχουν το προσωπικό τα απαιτούμενα προσόντα και ισχύουσες άδειες, και τηρούνται φάκελοι προσωπικού;","Φάκελοι προσωπικού","",1,false,[]],["JCI SQE.8 · ISO 9001 7.2","Έχει ολοκληρώσει το προσωπικό την ετήσια υποχρεωτική εκπαίδευση (ΚΑΡΠΑ, πυροπροστασία, λοιμώξεις);","Μητρώο εκπαιδεύσεων","",1,false,[]],["ISO 9001 7.3 · JCI GLD","Γνωρίζει το προσωπικό την πολιτική ποιότητας, τους στόχους του τμήματος και πώς συμβάλλει;","Συνέντευξη","",1,false,[]],["JCI SQE · TEMOS T2","Υπάρχει επάρκεια προσωπικού ανά βάρδια και τρόπος κάλυψης απουσιών;","Πρόγραμμα βαρδιών","",1,false,[]]]},{"r":"ΣΥΜ","t":"Συμβάντα και βελτίωση","q":[["JCI QPS.7 · ISO 9001 10.2","Αναφέρονται τα συμβάντα και τα παρ’ ολίγον συμβάντα, και γνωρίζει το προσωπικό πώς γίνεται η αναφορά;","Συνέντευξη, μητρώο συμβάντων","",2,true,[]],["ISO 9001 10.2 · JCI QPS","Έχουν ολοκληρωθεί στην ώρα τους οι διορθωτικές ενέργειες από προηγούμενες επιθεωρήσεις και συμβάντα;","Κατάλογος ενεργειών","",1,false,[]],["ISO 9001 9.1 · JCI QPS.3","Παρακολουθεί το τμήμα τους δείκτες ποιότητας και συζητά τα αποτελέσματα στις συναντήσεις του;","Πρακτικά, δείκτες","",1,false,[]]]},{"r":"ΠΑΡ","t":"Παράπονα και επικοινωνία με τον ασθενή","q":[["JCI PFR.2 · TEMOS T8","Γνωρίζουν οι ασθενείς και οι συνοδοί πώς μπορούν να υποβάλουν παράπονο ή πρόταση, και απαντάται εγκαίρως;","Φυλλάδια, μητρώο παραπόνων","",1,false,[]],["JCI PFR · ISO 9001 9.1.2","Συλλέγεται και αξιοποιείται η γνώμη των ασθενών (ερωτηματολόγια ικανοποίησης);","Αποτελέσματα ερευνών","",1,false,[]],["JCI PFE · ISO 9001 8.2.1","Ενημερώνονται οι ασθενείς και οι οικογένειες για τη φροντίδα, τα φάρμακα και την έξοδο, με τρόπο που καταλαβαίνουν;","Φάκελοι, συνέντευξη","",1,false,[]]]},{"r":"ΔΙΕ","t":"Διεθνείς ασθενείς","q":[["TEMOS T2 · JCI PFR","Υπάρχει τρόπος διερμηνείας ή μετάφρασης όταν ο ασθενής δεν μιλά ελληνικά, και καταγράφεται;","Φάκελοι, διαδικασία","",1,false,["international"]],["TEMOS T3 · JCI PFR.1","Ενημερώνεται ο διεθνής ασθενής για το κόστος, τη φροντίδα και τα δικαιώματά του πριν από την έναρξη;","Φάκελοι","",1,false,["international"]],["TEMOS T4 · JCI ACC","Συντονίζεται η φροντίδα και η συνέχειά της με το γραφείο διεθνών ασθενών, και ενημερώνεται ο θεράπων ιατρός της χώρας του;","Φάκελοι","",1,false,["international"]],["TEMOS T7 · JCI ACC","Γίνεται παρακολούθηση μετά την έξοδο και καταγράφεται η επικοινωνία;","Φάκελοι","",1,false,["international"]]]}]}'::jsonb j),
tp as (insert into public.quality_audit_templates (organization_id, is_system, template_key, standard, standard_version, title, description, scope, department_types, active, version, source)
 select null, true, j->>'k', j->>'s', j->>'v', j->>'t', j->>'d', j->>'sc', array(select jsonb_array_elements_text(j->'dt')), true, 1, 'seed' from s
 on conflict on constraint quality_audit_templates_title_key do nothing returning id),
qs as (select ch.value->>'r' r, ch.value->>'t' t, q.value v, row_number() over (order by ch.ordinality, q.ordinality) p
 from s, jsonb_array_elements(j->'ch') with ordinality ch, jsonb_array_elements(ch.value->'q') with ordinality q)
insert into public.quality_audit_template_questions (template_id, organization_id, position, chapter_ref, chapter_title, clause_ref, question, guidance, evidence, weight, critical, areas)
select tp.id, null, qs.p, qs.r, qs.t, qs.v->>0, qs.v->>1, nullif(qs.v->>3, ''), nullif(qs.v->>2, ''), (qs.v->>4)::numeric, (qs.v->>5)::boolean, array(select jsonb_array_elements_text(qs.v->6)) from tp, qs;
